import React from 'react';
import { motion } from 'framer-motion';

const SkillBar = ({ name, rating, darkMode, delay }) => {
  const pct = (Math.min(rating, 5) / 5) * 100;
  return (
    <motion.div
      className="mb-5"
      initial={{ opacity: 0, x: -10 }}
      whileInView={{ opacity: 1, x: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay }}
    >
      <div className="flex justify-between mb-1.5">
        <span className="text-sm font-medium">{name}</span>
        <span className={`text-xs ${darkMode ? 'text-gray-400' : 'text-gray-600'}`}>{Math.min(rating, 5)}/5</span>
      </div>
      <div className={`w-full rounded-full h-2 ${darkMode ? 'bg-gray-700' : 'bg-gray-200'}`}>
        <motion.div
          className="h-2 rounded-full bg-gradient-to-r from-blue-500 to-violet-500"
          initial={{ width: 0 }}
          whileInView={{ width: `${pct}%` }}
          viewport={{ once: true }}
          transition={{ duration: 0.7, delay: delay + 0.1, ease: 'easeOut' }}
        />
      </div>
    </motion.div>
  );
};

