import React, { useState, useEffect } from 'react';
import { Sun, Moon } from 'lucide-react';

const Navigation = ({ darkMode, toggleDarkMode, handleScroll }) => {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const navItems = [
    { label: 'About', id: 'about' },
    { label: 'Experience', id: 'work' },
    { label: 'Skills', id: 'skills' },
    { label: 'Education', id: 'education' },
    { label: 'Testimonials', id: 'testimonials' },
    { label: 'Contact', id: 'contact' },
  ];

  const handleNav = (id) => {
    handleScroll(id);
    setMenuOpen(false);
  };

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? darkMode
            ? 'bg-gray-900/90 backdrop-blur-md shadow-lg border-b border-gray-700/50'
            : 'bg-white/90 backdrop-blur-md shadow-lg border-b border-gray-200/50'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
        <button
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className={`font-bold text-xl tracking-tight ${!scrolled || darkMode ? 'text-white' : 'text-gray-900'}`}
        >
          KM<span className="text-blue-500">.</span>
        </button>

        {/* Desktop links */}
        <div className="hidden md:flex items-center gap-8">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNav(item.id)}
              className={`text-sm font-medium transition-colors duration-200 hover:text-blue-400 ${
                !scrolled || darkMode ? 'text-white/80 hover:text-white' : 'text-gray-600 hover:text-blue-500'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4">
          {/* Dark mode toggle */}
          <button
            onClick={toggleDarkMode}
            aria-label="Toggle dark mode"
            className={`w-14 h-7 flex items-center rounded-full p-1 transition-colors duration-500 shadow-md ${
              darkMode
                ? 'bg-gradient-to-r from-yellow-400 to-orange-500'
                : 'bg-gradient-to-r from-blue-500 to-indigo-600'
            }`}
          >
            <div
              className={`w-5 h-5 bg-white rounded-full shadow transform transition-transform duration-500 flex items-center justify-center ${
                darkMode ? 'translate-x-7' : 'translate-x-0'
              }`}
            >
              {darkMode ? (
                <Moon size={11} className="text-gray-700" />
              ) : (
                <Sun size={11} className="text-yellow-500" />
              )}
            </div>
          </button>

          {/* Mobile hamburger */}
          <button
            onClick={() => setMenuOpen(!menuOpen)}
            className={`md:hidden flex flex-col gap-1.5 p-1 ${darkMode ? 'text-white' : 'text-gray-900'}`}
            aria-label="Toggle menu"
          >
            <span className={`block w-5 h-0.5 transition-all duration-300 ${!scrolled || darkMode ? 'bg-white' : 'bg-gray-900'} ${menuOpen ? 'rotate-45 translate-y-2' : ''}`} />
            <span className={`block w-5 h-0.5 transition-all duration-300 ${!scrolled || darkMode ? 'bg-white' : 'bg-gray-900'} ${menuOpen ? 'opacity-0' : ''}`} />
            <span className={`block w-5 h-0.5 transition-all duration-300 ${!scrolled || darkMode ? 'bg-white' : 'bg-gray-900'} ${menuOpen ? '-rotate-45 -translate-y-2' : ''}`} />
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <div className={`md:hidden px-6 pb-4 flex flex-col gap-3 ${darkMode ? 'bg-gray-900/95' : 'bg-white/95'}`}>
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => handleNav(item.id)}
              className={`text-sm font-medium text-left py-2 border-b transition-colors duration-200 hover:text-blue-500 ${
                darkMode ? 'text-gray-300 border-gray-700' : 'text-gray-600 border-gray-200'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      )}
    </nav>
  );
};

export default Navigation;
