import React, { useEffect } from 'react';
import { ChevronDown } from 'lucide-react';

const HeroSection = ({ handleScroll, darkMode }) => {
  useEffect(() => {
    const canvas = document.getElementById('particles');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    let particlesArray;
    let animationId;

    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    class Particle {
      constructor(x, y, directionX, directionY, size) {
        this.x = x;
        this.y = y;
        this.directionX = directionX;
        this.directionY = directionY;
        this.size = size;
      }

      draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2, false);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
        ctx.fill();
      }

      update(mouse) {
        if (this.x > canvas.width || this.x < 0) this.directionX = -this.directionX;
        if (this.y > canvas.height || this.y < 0) this.directionY = -this.directionY;

        const dx = mouse.x - this.x;
        const dy = mouse.y - this.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < 100) {
          this.x -= dx / 10;
          this.y -= dy / 10;
        }

        this.x += this.directionX;
        this.y += this.directionY;
        this.draw();
      }
    }

    function connect() {
      for (let a = 0; a < particlesArray.length; a++) {
        for (let b = a; b < particlesArray.length; b++) {
          const distance =
            (particlesArray[a].x - particlesArray[b].x) ** 2 +
            (particlesArray[a].y - particlesArray[b].y) ** 2;
          if (distance < (canvas.width / 7) * (canvas.height / 7)) {
            const opacity = 1 - distance / 20000;
            ctx.strokeStyle = `rgba(255, 255, 255, ${opacity})`;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(particlesArray[a].x, particlesArray[a].y);
            ctx.lineTo(particlesArray[b].x, particlesArray[b].y);
            ctx.stroke();
          }
        }
      }
    }

    function init() {
      particlesArray = [];
      const count = (canvas.width * canvas.height) / 9000;
      for (let i = 0; i < count; i++) {
        const size = Math.random() * 3 + 1;
        particlesArray.push(
          new Particle(
            Math.random() * (window.innerWidth - size * 2),
            Math.random() * (window.innerHeight - size * 2),
            Math.random() * 1 - 0.5,
            Math.random() * 1 - 0.5,
            size
          )
        );
      }
    }

    function animate() {
      animationId = requestAnimationFrame(animate);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particlesArray.forEach((p) => p.update(mouse));
      connect();
    }

    const mouse = { x: null, y: null };

    const onMouseMove = (e) => { mouse.x = e.x; mouse.y = e.y; };
    const onTouchMove = (e) => { mouse.x = e.touches[0].clientX; mouse.y = e.touches[0].clientY; };
    const onTouchEnd = () => { mouse.x = null; mouse.y = null; };
    const onResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      init();
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('touchmove', onTouchMove);
    window.addEventListener('touchend', onTouchEnd);
    window.addEventListener('resize', onResize);

    init();
    animate();

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);
      window.removeEventListener('resize', onResize);
    };
  }, []);

  return (
    <div
      className={`min-h-screen relative flex flex-col justify-center items-center text-white p-8 transition-colors duration-500 ${
        darkMode
          ? 'bg-gradient-to-br from-gray-950 via-gray-900 to-gray-800'
          : 'bg-gradient-to-br from-blue-700 via-indigo-600 to-violet-600'
      }`}
    >
      <canvas id="particles" className="absolute inset-0 w-full h-full pointer-events-none" />

      <div className="relative z-10 max-w-4xl mx-auto text-center">
        {/* Profile image with gradient ring */}
        <div className="relative inline-block mb-8">
          <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-blue-400 via-violet-400 to-pink-400 blur-sm scale-110 opacity-70" />
          <img
            src="./images/profile_v1.jpg"
            alt="Kumar Murthy"
            className="relative w-48 h-48 rounded-full object-cover object-center shadow-2xl border-4 border-white/20"
          />
        </div>

        {/* Gradient name */}
        <h1 className="text-5xl md:text-6xl font-extrabold mb-3 tracking-tight">
          <span className="bg-gradient-to-r from-white via-blue-100 to-white bg-clip-text text-transparent">
            Kumar Murthy
          </span>
        </h1>

        <h2 className="text-xl md:text-2xl font-medium text-white/80 mb-4 tracking-wide">
          Senior Product Manager
        </h2>

        <p className="text-base md:text-lg font-semibold mb-10 text-white/70 max-w-xl mx-auto">
          Empowering AI Conversations for a Smarter Future
        </p>

        <div className="flex gap-4 justify-center flex-wrap">
          <button
            onClick={() => handleScroll('work')}
            className="bg-white text-blue-700 px-7 py-3 rounded-full font-semibold shadow-lg hover:shadow-xl hover:scale-105 transition-all duration-200"
          >
            View Work
          </button>
          <button
            onClick={() => handleScroll('contact')}
            className="border-2 border-white/70 text-white px-7 py-3 rounded-full font-semibold hover:bg-white/10 hover:border-white hover:scale-105 transition-all duration-200"
          >
            Get in Touch
          </button>
        </div>
      </div>

      {/* Scroll indicator */}
      <button
        onClick={() => handleScroll('about')}
        className="absolute bottom-8 left-1/2 -translate-x-1/2 text-white/50 hover:text-white/90 transition-colors duration-200 animate-bounce"
        aria-label="Scroll down"
      >
        <ChevronDown size={32} />
      </button>
    </div>
  );
};

export default HeroSection;
